<script setup>
import {onMounted,onUnmounted,ref} from 'vue'
import {api,label,delay} from '../api/library.js'
import CopyButton from '../components/CopyButton.vue'
const pageUrl=window.location.href
const files=ref([]),page=ref(1),total=ref(0),busy=ref(false),msg=ref(''),selected=ref(null),size=ref(3),parts=ref([]),splitting=ref(false)
let alive=true;onUnmounted(()=>alive=false)
async function load(n=1){if(busy.value)return;busy.value=true;msg.value='';try{const d=await api(`/files?page=${n}&per_page=10`);files.value=d.files;page.value=d.page;total.value=d.total;selected.value=null;parts.value=[]}catch(e){msg.value=e.message}finally{busy.value=false}}
onMounted(()=>load())
function choose(f){selected.value=selected.value===f?null:f;parts.value=[];msg.value=''}
function format(f){return /\.epub$/i.test(f.file_name)?'EPUB':/\.txt$/i.test(f.file_name)?'TXT':'文件'}
function weight(n){return n>=1048576?`${(n/1048576).toFixed(1)} MB`:`${(n/1024).toFixed(1)} KB`}
async function split(){if(splitting.value||!selected.value)return;const f=selected.value;if(!window.confirm('分割 TXT 不消耗下载次数。开始分割？'))return;splitting.value=true;parts.value=[];try{const {taskId}=await api('/novels/split',{filename:f.file_name,chunkSizeMB:size.value});while(alive){const d=await api('/novels/split/'+encodeURIComponent(taskId));if(!alive)return;if(d.status==='error')throw new Error(d.error);if(d.status==='done'){parts.value=d.outputFiles;msg.value=`已生成 ${parts.value.length} 个分卷。`;break}msg.value=`正在分卷　${d.progress}%`;await delay(800)}}catch(e){msg.value=e.message}finally{splitting.value=false}}
</script>
<template><section><div class="list-heading"><h1>我的<em>文件</em></h1><button :disabled="busy||splitting" @click="load(page)">刷新列表</button></div>
<p v-if="!files.length && !msg" class="empty">{{busy?'正在读取文件…':'还没有下载记录。从番茄或七猫选一本书开始。'}}</p>
<div class="file-list" v-else-if="files.length"><article class="file" v-for="f in files" :key="f.source+f.file_name">
<div class="file-info"><span class="file-type" aria-label="文件格式">{{format(f)}}</span><div class="caption"><h3>{{f.book_name}}</h3><div class="meta"><span v-if="f.author">{{f.author}}</span><span>{{label[f.source]}}</span><span>{{f.size?weight(f.size):'文件校验中'}}</span><time v-if="f.mtime" :title="f.mtime">{{String(f.mtime).slice(0,10)}}</time></div></div></div>
<div class="file-actions"><a class="action" :href="`/api/${f.source==='qimao'?'qimao/':''}file/${encodeURIComponent(f.book_name)}`" download>下载文件</a><button v-if="format(f)==='TXT'" :aria-expanded="selected===f" :disabled="splitting" @click="choose(f)">{{selected===f?'收起分卷':'TXT 分卷'}}</button></div>
<div v-if="selected===f" class="split-options appear"><label>每卷大小 <select v-model="size" :disabled="splitting"><option v-for="v in [0.5,1,2,3,5,10,20,50]" :value="v">{{v}} MB</option></select></label> <button :disabled="splitting" @click="split">开始分割</button><p><small>最多 10 卷，不消耗下载次数。</small></p><p v-for="part in parts" :key="part.name"><a :href="`/api/novels/download/${encodeURIComponent(f.file_name.replace(/\.txt$/i,''))}/${encodeURIComponent(part.name)}`" download>{{part.name}}　{{part.sizeText}}</a></p></div>
</article></div>
<p class="notice" v-if="msg" role="status">{{msg}}</p><div class="row" v-if="total>10"><button :disabled="busy||splitting||page===1" @click="load(page-1)">上一页</button>{{page}}<button :disabled="busy||splitting||page*10>=total" @click="load(page+1)">下一页</button></div><details><summary>手机上无法保存文件？</summary><p>微信内置浏览器可能拦截下载。复制链接，在系统浏览器打开并登录，再取回文件。</p><CopyButton :text="pageUrl" label="复制页面链接"/></details></section></template>
<style scoped>
.list-heading,.file-info,.file-actions,.meta{display:flex;align-items:center;gap:12px}.list-heading{justify-content:space-between;margin:10px 0 24px}.list-heading h1{margin:0}.file{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px;padding:18px 0;border-top:1px solid var(--line)}.file-list{border-bottom:1px solid var(--line)}.file-type{display:grid;place-items:center;flex:none;width:44px;height:54px;border:1px solid var(--line);border-radius:5px 11px 5px 5px;background:var(--surface);font-size:11px;letter-spacing:.07em;font-weight:700}.caption{min-width:0}.caption h3{font-size:17px;line-height:1.4;margin:0 0 4px;overflow-wrap:anywhere}.meta{flex-wrap:wrap;gap:2px 10px;color:var(--muted);font-size:13px}.file-actions{gap:4px}.file-actions button{border:0;background:transparent;font-size:14px;color:var(--muted)}.file-actions a{background:var(--raised);color:var(--text)}.split-options{grid-column:1/-1;background:var(--surface);border-radius:12px;padding:14px;overflow-wrap:anywhere}.split-options p:last-child{margin-bottom:0}@media(max-width:590px){.file{grid-template-columns:1fr}.file-actions{margin-left:56px}.file-actions button,.file-actions a{padding:6px 12px}.list-heading>button{font-size:14px}}
@media(max-width:719px){.list-heading{margin:0 0 10px}.file{padding:12px 0;gap:5px}.file-info{gap:10px}.file-type{width:34px;height:43px;border-radius:2px;font-size:10px}.caption h3{font-family:var(--serif);font-size:16px;font-weight:600}.meta{font-size:12px}.file-actions{margin-left:44px}.file-actions a{border:none;background:none;color:var(--accent);padding-inline:0 12px}.split-options{border-radius:4px}}
</style>
